select pro.id pro_id, pro.major, pro.pro_code, pro.pro_sub_type, pro.pro_type, chengguo pro_name, sd.name apply_company, su.username apply_account, pt.apply_start_date, pt.apply_end_date, pt.expert_start_time, pt.expert_end_time, pt.expert_start_time_second, pt.expert_end_time_second, pt.check_start_time, pt.check_end_time, pt.task_stat, pro.pro_stat, pro.pro_result_code proCode, pro.declare_account declareAccount, (select qg.name from ass_qc_group qg where qg.groupid = pro.group_id and qg.taskid = pro.publish_task_id limit 1) qcGroupName, case pro.pro_sub_type when 'design' then (select r.review_result from ass_surver_review_design_result r where r.pro_id = pro.id order by r.id desc limit 1) when 'software' then (select r.review_result from ass_surver_review_soft_result r where r.pro_id = pro.id order by r.id desc limit 1) when 'standard' then (select r.review_result from ass_surver_review_standard_result r where r.pro_id = pro.id order by r.id desc limit 1) when 'consulting' then (select r.review_result from ass_surver_review_consult_result r where r.pro_id = pro.id order by r.id desc limit 1) when 'contribution' then (select r.review_result from ass_surver_review_surver_result r where r.pro_id = pro.id order by r.id desc limit 1) else '' end latestReviewResult, case pro.pro_sub_type when 'design' then (select r.remarks from ass_surver_review_design_result r where r.pro_id = pro.id order by r.id desc limit 1) when 'software' then (select r.remarks from ass_surver_review_soft_result r where r.pro_id = pro.id order by r.id desc limit 1) when 'standard' then (select r.remarks from ass_surver_review_standard_result r where r.pro_id = pro.id order by r.id desc limit 1) when 'consulting' then (select r.remarks from ass_surver_review_consult_result r where r.pro_id = pro.id order by r.id desc limit 1) when 'contribution' then (select r.remarks from ass_surver_review_surver_result r where r.pro_id = pro.id order by r.id desc limit 1) else '' end latestReviewRemarks, case when pro.pro_sub_type = 'design' then ( select group_concat(sdu.username separator '、') from ass_surver_desigin_contribute_user_info sdu where sdu.pro_id = pro.id and ifnull(sdu.deleted,0) = 0 ) when pro.pro_sub_type = 'software' then ( select group_concat(sdu.username separator '、') from ass_surver_desigin_contribute_user_info sdu where sdu.pro_id = pro.id and ifnull(sdu.deleted,0) = 0 ) when pro.pro_sub_type = 'standard' then ( select group_concat(sdu.username separator '、') from ass_surver_desigin_contribute_user_info sdu where sdu.pro_id = pro.id and ifnull(sdu.deleted,0) = 0 ) when pro.pro_sub_type = 'contribution' then ( select group_concat(sdu.username separator '、') from ass_surver_desigin_contribute_user_info sdu where sdu.pro_id = pro.id and ifnull(sdu.deleted,0) = 0 ) else '' end memberList,
case pro.pro_sub_type when 'design' then (select ifnull(t.eliminated,0) from ass_surver_design_apply_table_info t where t.pro_id = pro.id order by t.id desc limit 1) when 'software' then (select ifnull(t.eliminated,0) from ass_surver_soft_apply_table_info t where t.pro_id = pro.id order by t.id desc limit 1) when 'standard' then (select ifnull(t.eliminated,0) from ass_surver_standard_apply_table_info t where t.pro_id = pro.id order by t.id desc limit 1) when 'contribution' then (select ifnull(t.eliminated,0) from ass_surver_excellent_apply_table_info t where t.pro_id = pro.id order by t.id desc limit 1) else 0 end eliminated,
(select egn.name from ass_award_pro_expert_group pegn join ass_award_expert_group egn on egn.groupid = pegn.groupid and egn.taskid = pegn.taskid where pegn.proid = pro.id limit 1) expertGroupName from boot_do.ass_award_enterprise_project pro JOIN sys_user su on pro.create_uid = su.user_id JOIN sys_dept sd ON su.dept_id = sd.dept_id JOIN ass_award_publish_task pt on pro.publish_task_id = pt.id
and pt.association_userid = #{associationUserId}
and pt.association_userid = #{ass_worker_uid}
join ass_award_pro_expert_group peg on peg.proid = pro.id join ass_award_expert_group eg on eg.groupid = peg.groupid and eg.taskid = peg.taskid join add_special_info si on si.group_name = eg.name and si.user_id = #{scoreSpecialistUid} and si.pro_type = 'surver_pro_group' and si.deleted = 0
join ass_award_assign_project asignPro on asignPro.pro_id = pro.id and asignPro.uid = #{ass_assign_uid}
and asignPro.assign_uid = #{pro_assign_uid}
and asignPro.assign_uid != -100
join ass_award_project_score sr on pro.id = sr.pro_id join add_special_info sai on sr.score_uid = sai.user_id and sai.login_account = #{scoreAccount} and sai.deleted = 0
pro.pro_type = 'surver_pro' AND pro.major IS NOT NULL and pro.pro_sub_type = #{proSubType} and opt_uid = #{optUid} and pro.id = #{proId} and publish_task_id = #{taskId}
AND EXISTS ( SELECT 1 FROM ass_award_pro_expert_group cpeg JOIN ass_award_expert_group ceg ON ceg.groupid = cpeg.groupid AND ceg.taskid = cpeg.taskid JOIN add_special_info csi ON csi.group_name = ceg.name AND csi.task_id = cpeg.taskid AND csi.user_id = #{contactUserId} AND csi.pro_type = 'surver_view_scope' AND csi.deleted = 0 WHERE cpeg.proid = pro.id )
and ( pro.pro_result_code like #{keyWord} or exists( SELECT sd.name FROM boot_do.sys_dept sd join sys_user su on sd.dept_id = su.dept_id where su.user_id = qa.opt_uid and sd.name like #{keyWord} ) or exists( select username from sys_user where user_id = qa.opt_uid and username like #{keyWord} ) or pro.pro_stat like #{keyWord} )
and pro.create_uid = #{enterpriseUid}
AND pro.chengguo LIKE concat('%', #{filterProName}, '%')
AND sd.name LIKE concat('%', #{filterApplyCompany}, '%')
AND pro.major LIKE concat('%', #{filterMajor}, '%')
AND pro.declare_account LIKE concat('%', #{filterDeclareAccount}, '%')
AND ifnull(pro.qc_group_name, pro.pro_group_name) LIKE concat('%', #{filterQcGroupName}, '%')
AND EXISTS ( SELECT 1 FROM ass_award_pro_expert_group peg2 JOIN ass_award_expert_group eg2 ON eg2.groupid = peg2.groupid AND eg2.taskid = peg2.taskid WHERE peg2.proid = pro.id AND eg2.name LIKE concat('%', #{filterExpertGroupName}, '%') )
AND (CASE pro.pro_sub_type WHEN 'design' THEN (SELECT ifnull(t.eliminated,0) FROM ass_surver_design_apply_table_info t WHERE t.pro_id = pro.id ORDER BY t.id DESC LIMIT 1) WHEN 'software' THEN (SELECT ifnull(t.eliminated,0) FROM ass_surver_soft_apply_table_info t WHERE t.pro_id = pro.id ORDER BY t.id DESC LIMIT 1) WHEN 'standard' THEN (SELECT ifnull(t.eliminated,0) FROM ass_surver_standard_apply_table_info t WHERE t.pro_id = pro.id ORDER BY t.id DESC LIMIT 1) WHEN 'contribution' THEN (SELECT ifnull(t.eliminated,0) FROM ass_surver_excellent_apply_table_info t WHERE t.pro_id = pro.id ORDER BY t.id DESC LIMIT 1) ELSE 0 END) = #{filterEliminated}
AND pro.pro_stat = #{filterProStat}
order by ${sort} ${order}
order by pro.id desc
limit #{offset}, #{limit}

