and asignPro.assign_uid != -100
join ass_award_project_score sr on pro.id = sr.pro_id join add_special_info sai on sr.score_uid = sai.user_id and sai.login_account = #{scoreAccount} and sai.deleted = 0
pro.pro_type = 'surver_pro' AND pro.major IS NOT NULL and pro.pro_sub_type = #{proSubType} and opt_uid = #{optUid} and pro.id = #{proId} and publish_task_id = #{taskId}
AND EXISTS ( SELECT 1 FROM ass_award_pro_expert_group cpeg JOIN ass_award_expert_group ceg ON ceg.groupid = cpeg.groupid AND ceg.taskid = cpeg.taskid JOIN add_special_info csi ON csi.group_name = ceg.name AND csi.task_id = cpeg.taskid AND csi.user_id = #{contactUserId} AND csi.pro_type = 'surver_view_scope' AND csi.deleted = 0 WHERE cpeg.proid = pro.id )
and ( pro.pro_result_code like #{keyWord} or exists( SELECT sd.name FROM boot_do.sys_dept sd join sys_user su on sd.dept_id = su.dept_id where su.user_id = qa.opt_uid and sd.name like #{keyWord} ) or exists( select username from sys_user where user_id = qa.opt_uid and username like #{keyWord} ) or pro.pro_stat like #{keyWord} )
and pro.create_uid = #{enterpriseUid}
